/* 计划运行中胶囊保持「已登录」，不打扰运行中的计划；但学校明确说登录失效（expired）时
 * 必须走「登录已失效」，电脑在自动登录时走「自动登录中…」——否则计划栏运行提醒和
 * 顶部「登录已失效」横幅永远出不来（决策 014 第 8 条）。网络原因的「暂时无法确认」仍保持原样。 */
const busyExpired = S.login.result === "expired" && S.login.present !== false;

/* 登录是否已失效（EX02）：session_expired、快照明说没有会话，或电脑最近一次学校校验
 * 说已失效（last_check_state=expired：本机会话文件还在也可能被学校判失效）；
 * 与 loginLine/ingest 同一口径。 */
loginRaw(login) {
  return !!login && (!!login.session_expired || login.session_present === false
    || login.last_check_state === "expired");
},

/* 给 flow 时：电脑正在自动重新登录就不算失效（不出失效横幅、不写已失效）；
 * 不给 flow 时保持原口径（底栏「重新登录」主钮用它，那条入口会接上正在跑的这一场）。 */
loginExpired(login, flow) {
  if (!PhoneModel.loginRaw(login)) return false;
  return flow === undefined ? true : !PhoneModel.loginRecovering(login, flow);
},

loginLine(login, setup, flow) {
  const s = setup || {};
  if (PhoneModel.loginRaw(login) && PhoneModel.loginRecovering(login, flow)) {
    return "电脑正在自动重新登录。";
  }
  const expired = PhoneModel.loginExpired(login);
  const has = !!s.saved && !s.paused;
  const ocrOn = !!s.ocr_ready;
  return (expired ? "电脑上的登录已失效。" : "电脑上的登录有效。")
    + (has ? (ocrOn ? "失效时电脑会自己重新登录。" : "失效时只需在这里输验证码。")
           : (ocrOn ? "电脑上没保存账号，重新登录要输账号和密码。"
                    : "电脑上没保存账号，重新登录要输账号、密码和验证码。"));

/* 「自动登录中」只在两种情况下成立：学校判失效且后端说电脑正在恢复（setLogin 置位），
 * 或中继里确有一场电脑自己发起、还在进行、没转人工的登录（receiveReloginState 置位）。
 * 这里只负责收回，不置位：结论为 valid、已转人工、结论不是 expired 又没有这样一场中继时，
 * S.autoLogin 都不该还亮着，否则顶栏胶囊会一直停在「自动登录中…」。 */
function reconcileAutoLogin() {
  if (!S.autoLogin) return;
  if (S.login.handoff || S.login.result === "valid") { S.autoLogin = false; return; }

function modeOf(item) {
  if (!item) return "unknown";
  const now = bnowS();
  if (now == null) return "unknown";   // 未校准：模式未知（后端仍是最终权威）
  const end = toTs(item.sign_end);
  if (end !== null && end <= now) return "closed";
  const start = toTs(item.sign_start);
  if (start !== null && start > now) return "pre_register";
  return "instant_signup";
}

/* 活动行显示自己的执行模式：预报名 / 立即报名（抢名额）；已截止由状态格标示 */
if (state === "waiting" || state === "open") {
  sub.push('<span class="activity-flags"><span class="activity-flag">' + esc(modeText(modeOf(item))) + "</span></span>");
}

/* 开放状态（原型 stOf，Phone.dc.html:489-493）：signed → closed（报名截止已过，与电脑
 * classify_signup_mode 同一口径）→ open（已到开放时刻）→ pre → unknown（待公布）。
 * 时钟不可用（nowS 为 null）时分辨不出 open/closed，按 pre/unknown 呈现「待校准」，
 * 不在没有可信时钟时假装「已开放」 */
stOf(item, nowS) {
  if (!item || item.signed) return "signed";
  if (item.closed) return "closed";
  const open = PhoneModel.openEpochOf(item);
  if (nowS !== null && nowS !== undefined) {
    const end = PhoneModel.schoolSec(item && item.sign_end);
    if (end !== null && nowS >= end) return "closed";
    if (open > 0 && nowS >= open) return "open";
  }
  return open > 0 ? "pre" : "unknown";
},

/* 底栏副题（G02/LD01 先照原型补）：已选场按开放状态分「立即报名 / 预报名」两档计数，
   同原型 review sheet 上方的 summary 句式；开放状态按 businessNowS 判定，不读手机时钟 */
planSummary(items, nowS) {
  const list = items || [];
  let instant = 0;
  list.forEach((item) => {
    const open = PhoneModel.openEpochOf(item);
    if (open > 0 && nowS !== null && nowS !== undefined && open <= nowS) instant += 1;
  });
  const pre = list.length - instant;
  return [instant ? instant + " 场立即报名" : "", pre ? pre + " 场预报名" : ""]
    .filter(Boolean).join("，");

for spec in specs:
    start = parse_timestamp(spec.act_start)
    end = parse_timestamp(spec.act_end)
    if start is None or end is None or end <= start:
        continue          # 选中活动自身缺时间已由 activity_time_unknown 报过
    if intervals_overlap(start, end, signed_start, signed_end):

/* 与已报名活动举办时间重叠的那一场（没有返回 null）：和 validateSelection 同一套半开区间比较。
 * 时刻表据此直接禁选并写明冲突对象，不等勾上以后再报错。 */
function signedClash(item) {
  if (!item || item.signed) return null;
  const start = toTs(item.act_start);
  const end = toTs(item.act_end);
  if (!start || !end || end <= start) return null;
  return S.items.find((other) => {

/* 与已报名活动举办时间重叠的那一场（半开区间，与电脑 signedClash 同一规则）。
 * 已报名、已截止的行本身不算；没有完整举办时段的行无从判断，不算 */
signedClash(item, items) {
  if (!item || item.signed || item.closed) return null;
  const a = PhoneModel.actRange(item);
  if (!a) return null;
  return (items || []).find((other) => {
    if (!other || !other.signed || other.id === item.id) return false;
    const b = PhoneModel.actRange(other);
    return !!b && a.s < b.e && b.s < a.e;
  }) || null;
},

/* 与某场举办时段重叠的第一场（G05 行警 / LD04 的 hitSel；半开区间同 signedClash） */
overlapFirst(item, others) {
  const a = PhoneModel.actRange(item);
  if (!a) return null;
  return (others || []).find((other) => {
    if (!other || other.id === item.id) return false;
    const b = PhoneModel.actRange(other);
    return !!b && a.s < b.e && b.s < a.e;
  }) || null;
},
/* LD04 勾选冲突提示条（原型 toggle 的 notice，Phone.dc.html:700） */
conflictNotice(item, hit) {
  return "「" + ((item && item.name) || "") + "」与「" + ((hit && hit.name) || "")
    + "」的活动时间重叠，只能选其中一场。已保留原选择。";

if (state === "failed") {
  /* 刷新核对确认过已报名：照原型 card.verify 改成「报名成功」（先判它，否则会被「待核对」截走） */
  if (typeof verifiedSigned === "function" && verifiedSigned(task)) return "报名成功";
  /* 电脑睡眠盖住了开放时刻、一次都没提交（LS22 / PB15）：原型动词「错过了」 */
  if (typeof taskMissedBySleep === "function" && taskMissedBySleep(task)) return taskLabel("missed");
  /* 结果没确认 / 登录状态未知都不是「失败」：标签必须留出核对空间（「未提交」是代码独有） */
  if (task.stop_reason === "unconfirmed") return "待核对";
  if (task.stop_reason === "auth_unavailable") return "未提交";
  /* 名额已满是学校给的结束结论，不是工具失败（架构方案 3.3） */
  if (task.stop_reason === "full") return "名额已满";
}

function taskLabel(state) {
  return { queued: "排队", waiting: "等待开放", submitting: "提交中", success: "报名成功", already_signed: "已报名", failed: "报名未成功", canceled: "已取消",
    /* 原型任务卡动词表含 missed（LS22 / PB15）；后端没有这个状态，由 taskMissedBySleep 推导 */
    missed: "错过了" }[state] || "处理中";

} else if (stop === "unconfirmed") {
  /* 已发出的请求撤不回来：只陈述「发过几次、没拿到回应」，不下失败结论（原型 finishState） */
  detail = "已提交 " + tried + " 次，没拿到确定回应；结束时向学校核对也没查到结果。去活动页看一眼，或稍后刷新核对。工具不会再自动重发。";

/* 顺序和颜色照原型 .stats：已报名 ok、名额已满 wait、报名未成功 bad、错过了 bad、待核对 ask、已取消 wait */
const cells = [[c.ok, "已报名", "ok"], [c.full, "名额已满", "wait"], [c.bad, "报名未成功", "bad"],
  [c.missed, "错过了", "bad"], [c.pending, "待核对", "ask"], [c.canceled, "已取消", "wait"]].filter((cell) => cell[0] > 0);

const failedFull = st === "failed" && String(t.stop_reason || "") === "full";
const failedAsk = st === "failed" && String(t.stop_reason || "") === "unconfirmed";
const map = {
  waiting: ["", isPre ? "等待开放" : "准备报名"],
  submitting: ["run", "提交中"],
  success: ["ok", "报名成功"],
  already_signed: ["ok", "报名成功"],
  failed: [failedFull ? "" : (failedAsk ? "ask" : "bad"),
           failedFull ? "名额已满" : (failedAsk ? "待核对" : "报名未成功")],
  canceled: ["", "已取消"],
};

} else if (st === "canceled") {                    // RS02（Phone:580/877）
  const reason = String(t.reason || "");
  detail = reason === "计划已停止" ? "计划已停止，这一场没有提交"
    : (reason || "已取消");
} else if (st === "success") {                     // RS02 原型句（Phone:564）
  detail = "学校回“操作成功”，结束时向学校核对过：已报名";
} else if (failedFull) {                           // RS02 原型句（Phone:560）
  detail = "学校说报名人数已满，这一场到此结束，不再提交。不是工具出错。已提交 "
    + attempts + " 次";
} else if (failedAsk) {                            // RS02 原型句（Phone:565）
  detail = "已提交 " + attempts + " 次，没拿到确定回应；结束时向学校核对也没查到结果。"
    + "去活动页看一眼，或稍后刷新核对。工具不会再自动重发。";

taskText(task) {
  const t = task || {};
  const st = String(t.status || "");
  const stop = String(t.stop_reason || "");
  if (st === "success" || st === "already_signed") return "已报名";
  if (stop === "full") return "名额已满（学校说满了，不再提交，不是工具出错）";
  if (stop === "unconfirmed") return "待核对（去活动页看一眼，工具不会再自动重发）";
  if (st === "failed" || st === "canceled") {
    return "报名未成功" + (t.outcome_label ? "：" + t.outcome_label : (st === "canceled" ? "：已取消" : ""));
  }

def rank(a):
    # 未开放的排最前，其次开放中，已报名的垫底；时间未知时全部同档
    if a["signed"]:
        return 2
    if filter_now is None:
        return 1
    try:
        return 0 if filter_now < parse_ts(a["sign_start"]) else 1
    except Exception:
        return 1

/* 按天分组的车站时刻表：正在开放 → 「现在」线 → 按天 → 待公布 → 已报名 → 已截止
 * （LS01：后三组的顺序照原型 Main.dc.html 的 order 数组，已报名在已截止前） */
function groupTimetable(rows) {
  const open = [];
  const unknown = [];
  const closed = [];
  const signed = [];
  const days = new Map();

const byStart = (a, b) => (toTs(a.sign_start) || Infinity) - (toTs(b.sign_start) || Infinity) || String(a.name).localeCompare(String(b.name), "zh");
let html = "";
if (open.length) html += groupHtml("正在开放", open.sort(byStart), "open", "现在就能报");
if (open.length || days.size) html += nowlineHtml();
Array.from(days.keys()).sort((a, b) => Number(a) - Number(b)).forEach((key) => {
  const dayMs = Number(key);
  html += groupHtml(dayLabel(dayMs), days.get(key).sort(byStart), "day");
});
if (unknown.length) html += groupHtml("报名时间待公布", unknown.sort(byStart), "unknown", "公布以后才能到点报名");
if (signed.length) html += groupHtml("已报名", signed.sort(byStart), "signed");
/* 组名与旁注照原型 Main.dc.html:1922：已截止的场次只能查看 */
if (closed.length) html += groupHtml("已截止", closed.sort(byStart), "closed", "只能查看");

function paintChips() {
  /* 状态胶囊带计数（原型样式）：可报名/已报名/全部按全量数据算；
   * 可报名排除已截止（只能查看），已报名单独计，剩下是已截止 */
  const free = S.items.filter(isEligibleForPlan).length;
  const signed = S.items.filter((item) => item.signed).length;
  /* 没有可信现在时，可报名/已截止的划分无法确定：计数显示待确认而不是伪 0 */
  const counts = { free: bnowS() !== null || !S.items.length ? free : "待确认",
                   signed, all: S.items.length };

/* 分区：手机上先看「今天」，再看「即将开放」，已报名的折起来。
 * 24 小时内开放（或已经在报）的算今天：手机上真正要动手的就是这些。 */
bucketOf(item, nowS) {
  if (!item) return "upcoming";
  if (item.signed) return "signed";
  const open = PhoneModel.openEpochOf(item);
  if (!(open > 0)) {
    // 缺开放时间的只能算「以后」，但截止还没到的仍然可勾选
    return item.closed ? "signed" : "upcoming";
  }
  return open <= nowS + 86400 ? "today" : "upcoming";
},

/* G07 分组（原型 groups 构建的组名序，Phone.dc.html:728-731）：今天/明天/后天按
 * openEpochOf 的北京时间日历日（dayOf 即 UTC+8 日序）与业务此刻比对；原型只演示到后天，
 * 真实列表有更晚的场次，归入「更晚开放」（沿用既有空态句的措辞），不丢行 */
groupKeyOf(item, st, nowS, wallS) {
  if (st === "signed") return "已报名";
  if (st === "open") return "正在开放";
  if (st === "closed") return "已截止";
  if (st === "unknown") return "待公布";
  const base = nowS !== null && nowS !== undefined ? nowS : wallS;
  const diff = PhoneModel.dayOf(PhoneModel.openEpochOf(item)) - PhoneModel.dayOf(base);
  if (diff === 1) return "明天";
  if (diff === 2) return "后天";
  if (diff >= 3) return "更晚开放";
  return "今天";   // diff <= 0：开放日就是今天或已过（只在时钟不可用时出现）

const titles = ["正在开放", "今天", "明天", "后天", "待公布", "更晚开放", "已报名", "已截止"];
let nowPlaced = false;
const nowText = nowS !== null && nowS !== undefined
  ? PhoneModel.hhmmss(PhoneModel.beijingSecOf(nowS)).slice(0, 5) : null;
const groups = [];
titles.forEach((title) => {
  const rows = visible
    .filter((item) => PhoneModel.groupKeyOf(item, PhoneModel.stOf(item, nowS), nowS, wallS) === title)
    .map((item) => PhoneModel.rowView(item, ctx));
  if (!rows.length) return;
  const nowBefore = !nowPlaced && title !== "正在开放";   // 原型 nowPlaced：首个非开放组前插「现在」
  if (nowBefore) nowPlaced = true;

groups.push({
  title: title, n: rows.length,
  cls: title === "正在开放" ? "open" : (title === "已报名" ? "signed" : ""),
  note: title === "正在开放" ? "现在就能报" : (title === "已截止" ? "只能查看" : ""),
  nowBefore: nowBefore, now: nowText, rows: rows,
});

/* G08 段钮可见集（原型 visible 过滤的 seg 分支，Phone.dc.html:721-722）：
 * 「可报名」= 开放状态 open/pre，与段钮计数同一口径；关键词与时间档沿用 filterItems */
visibleItems(items, filter, nowS) {
  const status = (filter && filter.status) || "all";
  return PhoneModel.filterItems(items, { q: filter && filter.q, time: filter && filter.time, status: "all" }, nowS)
    .filter((item) => {
      const st = PhoneModel.stOf(item, nowS);
      if (status === "free") return st === "open" || st === "pre";
      if (status === "signed") return st === "signed";
      return true;
    });

def group_by_sign_start(specs: Iterable[TaskSpec]) -> list[list[TaskSpec]]:
    """按完整报名开放时间分组，返回从早到晚的并发批次。"""
    groups: dict[datetime, list[TaskSpec]] = {}
    for spec in specs:
        when = parse_timestamp(spec.sign_start)
        if when is None:
            continue
        groups.setdefault(when, []).append(spec)
    return [groups[key] for key in sorted(groups)]

/* 批次头照原型 batches：已开放的批次写「现在」，预报名写 hms（HH:MM:SS，跨天加「明天 / 后天」） */
const instant = modeOf(group.items[0]) === "instant_signup";
const count = group.items.length;
const note = instant ? "立即报名 " + count + " 场"
  : (count > 1 ? "预报名，同时提交 " + count + " 场" : "预报名 1 场");
const at = toTs(group.key);
return '<div class="bh"><b>' + esc(instant ? "现在" : (at === null ? "待公布" : hmsDay(at))) + "</b><span>" + esc(note) + "</span></div>"

function runCaption(view) {
  const count = view.count;
  if (view.phase === "submitting") {
    if (count > 1) return "正在提交 " + count + " 场，每场结果单独显示。";
    const task = view.task || {};
    const tried = Math.max(0, Math.floor(Number(task.attempts) || 0));
    const last = String(task.last_reason || "").trim();
    return "已提交 " + tried + " 次" + (last ? "，最近：" + last : "");
  }
  if (view.phase === "arming") {
    return count > 1 ? "已开放，正在准备 " + count + " 场，每场结果单独显示。" : "已开放，正在准备提交。";
  }
  return count > 1 ? "这一批 " + count + " 场同时提交，到点自动开始。" : "这一场等开放，到点自动开始。";

return keys.map((k) => {
  const b = map.get(k);
  const n = b.items.length;
  b.note = b.instant ? "立即报名 " + n + " 场"
    : (n > 1 ? "预报名，同时提交 " + n + " 场" : "预报名 1 场");
  return b;
});

tag = gap !== null && gap <= 5 ? "即将开放" : "等开放";
led = PhoneModel.ledOf(gap === null ? "--:--:--" : PhoneModel.hhmmss(gap),
  off ? "dim" : (gap !== null && gap <= 10 ? "red" : "amber"),
  "开放时间", targetText(open));
const same = wait.filter((t) => PhoneModel.taskOpenOf(t) === open).length;
sub = same > 1 ? "这一批 " + same + " 场同时提交，到点自动开始。"
               : "这一场等开放，到点自动开始。";

/* 学校时间（UTC+8）文本与换算纯函数。 */
const SCHOOL_TZ = "Asia/Shanghai";
const SCHOOL_OFFSET_S = 8 * 3600;
const SCHOOL_FMT = new Intl.DateTimeFormat("zh-CN", {
  timeZone: SCHOOL_TZ, year: "numeric", month: "2-digit", day: "2-digit",
  hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23",
});

function toTs(value) {
  if (!value) return null;
  const match = String(value).match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
  if (!match) return null;
  const [y, mo, d, h, mi, s] = match.slice(1).map(Number);
  if (mo < 1 || mo > 12 || d < 1 || d > 31 || h > 23 || mi > 59 || s > 59) return null;
  const utc = Date.UTC(y, mo - 1, d, h, mi, s);
  const check = new Date(utc);
  if (check.getUTCFullYear() !== y || check.getUTCMonth() !== mo - 1 ||
      check.getUTCDate() !== d || check.getUTCHours() !== h ||
      check.getUTCMinutes() !== mi || check.getUTCSeconds() !== s) return null;
  return utc / 1000 - SCHOOL_OFFSET_S;

function fmt(seconds) {
  let value = Math.max(0, Math.floor(seconds));
  const days = Math.floor(value / 86400);
  const hours = Math.floor((value % 86400) / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  const secs = value % 60;
  const pad = (number) => String(number).padStart(2, "0");
  if (days > 0) return days + "天 " + pad(hours) + ":" + pad(minutes);
  return pad(hours) + ":" + pad(minutes) + ":" + pad(secs);

function durText(seconds) {
  const value = Math.max(0, Math.floor(seconds));
  const days = Math.floor(value / 86400);
  const hours = Math.floor((value % 86400) / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  const secs = value % 60;
  if (days) return days + " 天 " + hours + " 时";
  if (hours) return hours + " 时 " + String(minutes).padStart(2, "0") + " 分";
  if (minutes) return minutes + " 分 " + String(secs).padStart(2, "0") + " 秒";
  return secs + " 秒";

businessNowS(model) {
  const c = model && model.clock;
  if (!c) return null;
